class {
  onCreate() {
    this.state = {
      todos: [],
      text: ""
    };
  }

  addTodo() {
    const text = this.state.text.trim();
    if (!text) return;
    this.state.todos = [
      ...this.state.todos,
      { text, done: false }
    ];
    this.state.text = "";
  }

  toggleTodo(index) {
    const todos = this.state.todos.slice();
    todos[index] = { ...todos[index], done: !todos[index].done };
    this.state.todos = todos;
  }

  onInput(event) {
    this.state.text = event.target.value;
  }
}

static function remaining(todos) {
  return todos.filter(todo => !todo.done).length;
}

<div>
  <input id="new-todo" value=component.state.text on-input("onInput")>
  <button id="add" on-click("addTodo")>Add</button>

  <div id="remaining">${remaining(component.state.todos)} left</div>

  <if(component.state.todos.length === 0)>
    <div id="empty">No todos yet</div>
  </if>
  <else>
    <ul id="list">
      <for|todo, index| of=component.state.todos>
        <li>
          <input type="checkbox" checked=todo.done on-click("toggleTodo", index)>
          ${todo.text}
        </li>
      </for>
    </ul>
  </else>
</div>

class {
  onCreate() {
    this.state = {
      todos: [],
      text: ""
    };
  }

  onInput(event) {
    this.state.text = event.target.value;
  }

  addTodo() {
    const text = this.state.text.trim();
    if (!text) return;
    this.state.todos = [
      ...this.state.todos,
      { text, done: false }
    ];
    this.state.text = "";
  }

  toggleTodo(index) {
    this.state.todos = this.state.todos.map((todo, i) =>
      i === index ? { ...todo, done: !todo.done } : todo
    );
  }
}

static function remaining(todos) {
  return todos.filter(todo => !todo.done).length;
}

<input id="new-todo" value=input.state.text on-input('onInput')>
<button id="add" on-click('addTodo')>Add</button>

<div id="empty" if=(input.state.todos.length === 0)>
  No todos yet
</div>
<ul id="list" else>
  <for|todo, index| of=input.state.todos>
    <li>
      <input type="checkbox" checked=todo.done on-click('toggleTodo', index)>
      ${todo.text}
    </li>
  </for>
</ul>

<div id="remaining">${remaining(input.state.todos)} left</div>

